function pickRows() {
  const c = ($("#pkCls") || {}).value || "", q = (($("#pkQ") || {}).value || "").trim();
  const list = S.roster.filter((s) => (!c || s.cls === c) && (!q || String(s.name).includes(q) || String(s.no) === q)).sort((a, b) => String(a.cls).localeCompare(String(b.cls)) || a.no - b.no);
  if (!list.length) return `<p class="muted">لا توجد طالبة مطابقة.</p>`;
  return `<table class="tbl"><thead><tr><th>رقم الورقة</th><th>الاسم</th><th>الفصل</th><th></th></tr></thead><tbody>${list.map((s) => `<tr><td class="num">${s.no}</td><td data-keep>${esc(s.name)}</td><td>${esc(s.cls)}</td><td><button class="btn sm" data-act="peek" data-s="${s.id}">فتح صفحتها</button></td></tr>`).join("")}</tbody></table>`;
}
