    if (share >= EW.shareHigh) add(2, `${wtxt} من ${x.skills.length} أقل من ${EW.low}%`); else if (share >= EW.shareMid) add(1, `${wtxt} من ${x.skills.length} أقل من ${EW.low}%`);
