A.qNewFor = (el) => { qImgDraft = undefined; modal(qForm({ type: "mc", text: "", opts: ["", "", "", ""], ans: 0, skill: el.dataset.skill, src: "" }), true); qPreview(0); };
let qImgDraft; // undefined: image unchanged, "": removed, data URL: newly chosen
