function loadScript(src) { return new Promise((res, rej) => { const s = document.createElement("script"); s.src = src; s.onload = res; s.onerror = () => rej({ message: "تعذّر تحميل مكتبة قراءة PDF." }); document.head.appendChild(s); }); }
async function fileToImages(file) {
  if (!/pdf$/i.test(file.type) && !/\.pdf$/i.test(file.name)) return [file];
  if (!window.pdfjsLib) { await loadScript("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"); await loadScript("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"); }
  const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise, out = [];
  for (let p = 1; p <= Math.min(pdf.numPages, 12); p++) {
    const page = await pdf.getPage(p), vp = page.getViewport({ scale: 1.6 }), c = document.createElement("canvas");
    c.width = vp.width; c.height = vp.height;
    await page.render({ canvasContext: c.getContext("2d"), viewport: vp }).promise;
    out.push(await new Promise((r) => c.toBlob(r, "image/jpeg", 0.85)));
  }
  return out;
}
let impDraft = [];
/** Turns one model-extracted item into a bank question, or null when it is not usable. */
function cleanImported(q, src, forced) {
  if (!q || typeof q.text !== "string" || !q.text.trim()) return null;
  const skill = forced || (sk(q.skill) ? q.skill : ""); if (!skill) return null;
  const str = (v) => (v == null ? "" : String(v).trim()), list = (a) => (Array.isArray(a) ? a.map(str).filter(Boolean) : []);
  const o = { type: QTYPES[q.type] && q.type !== "fig" ? q.type : "mc", text: q.text.trim(), opts: [], ans: 0, skill, src };
  if (o.type === "mc" || o.type === "mcj") { o.opts = list(q.opts).slice(0, 4); o.ans = Math.max(0, Math.min(o.opts.length - 1, +q.ans || 0)); if (o.opts.length < 2) return null; if (o.type === "mcj") { o.key = str(q.key); o.max = +q.max || 2; } }
  else if (o.type === "tf") { o.opts = ["صح", "خطأ"]; o.ans = +q.ans === 1 ? 1 : 0; }
  else if (o.type === "fix") { o.ul = str(q.ul); o.key = str(q.key); o.max = 1; if (!o.ul || !o.text.includes(o.ul)) return null; }
  else if (o.type === "match") { o.pairs = (Array.isArray(q.pairs) ? q.pairs : []).map((p) => ({ a: str(p && p.a), b: str(p && p.b) })).filter((p) => p.a && p.b).slice(0, 6); o.max = o.pairs.length; if (o.pairs.length < 2) return null; }
  else if (o.type === "compare") { o.x = str(q.x); o.y = str(q.y); o.crit = list(q.crit).slice(0, 6); o.key = str(q.key); o.max = +q.max || o.crit.length || 2; if (!o.x || !o.y || !o.crit.length) return null; }
  else { o.type = "essay"; o.key = str(q.key); o.max = +q.max || 1; }
  return o;
}
function impList() {
  return impDraft.length ? `<p><b>${impDraft.length}</b> سؤالًا مقروءًا. راجعي النص والإجابة والمهارة، وأزيلي العلامة عمّا لا تريدينه، ثم أضيفي. يمكنك تعديل أي سؤال بعد إضافته من «تعديل».</p>${impDraft.map((q, i) => `<div class="pick"><input type="checkbox" checked data-imp="${i}" aria-label="إضافة السؤال ${i + 1}"><div class="grow">${qCard(q)}<label class="fld">المهارة<select data-chg="impSkillSet" data-i="${i}">${skillOptions(q.skill)}</select></label></div></div>`).join("")}<div class="row end"><button class="btn" data-act="qImportAdd">إضافة المحدد إلى البنك</button></div>` : "لم أجد أسئلة مقروءة في الصور.";
}
async function runImport(files) {
  const out = $("#impOut"), forced = S.ui.impSkill || ""; impDraft = []; let skipped = 0;
  await guard(async () => {
    out.textContent = "جارٍ تجهيز الصفحات…";
    const imgs = [];
    for (const f of files) (await fileToImages(f)).forEach((im) => imgs.push({ im, src: f.name.replace(/\.[^.]+$/, "") }));
    for (let i = 0; i < imgs.length; i++) {
      out.textContent = `جارٍ قراءة الصورة ${i + 1} من ${imgs.length}…`;
      const r = await Store.sample.json(`هذه صورة سؤال أو صفحة من اختبار مدرسي. استخرج كل سؤال مقروء فيها كما كُتب، دون تغيير صياغته. تجاهل السؤال الذي لا يُفهم إلا برسم أو صورة أو جدول بيانات مرفق، وعُدّه في "skipped".
أجب بـ JSON فقط بالشكل {"skipped": عدد, "questions":[...]}. كل سؤال عنصر بأحد هذه الأشكال:
- اختيار من متعدد: {"type":"mc","text":"..","opts":["..",".."],"ans":رقم الخيار الصحيح بدءًا من 0}
- صح أو خطأ: {"type":"tf","text":"العبارة","ans":0 للصحيحة أو 1 للخاطئة}
- صوّبي ما تحته خط: {"type":"fix","text":"العبارة كاملة","ul":"الكلمة التي تحتها خط كما وردت في العبارة","key":"التصويب"}
- مزاوجة: {"type":"match","text":"تعليمات السؤال","pairs":[{"a":"من العمود الأول","b":"ما يناسبه من العمود الثاني"}]}
- اختاري ثم برّري: {"type":"mcj","text":"..","opts":[..],"ans":رقم,"key":"التبرير النموذجي"}
- مقارنة: {"type":"compare","text":"قارني بين ..","x":"الطرف الأول","y":"الطرف الثاني","crit":["وجه المقارنة"],"key":"الإجابة النموذجية"}
- مقالي (فسّري، علّلي، اذكري ..): {"type":"essay","text":"..","key":"إجابة نموذجية قصيرة","max":الدرجة إن كُتبت وإلا 1}
إن كانت الإجابة محددة في الصورة فاعتمدها، وإلا فأجب بما تعرفه علميًا من منهج العلوم للمرحلة المتوسطة.${forced ? "" : `\nأضف لكل سؤال "skill": معرّف المهارة الأنسب من القائمة.\n\nالمهارات (المعرّف | الفصل | المستوى | المهارة):\n${skillListText()}`}`, { images: [imgs[i].im], cache: false });
      const qs = Array.isArray(r) ? r : (r && r.questions) || []; skipped += (r && +r.skipped) || 0;
      qs.forEach((q) => { const c = cleanImported(q, imgs[i].src === "image" ? "سؤال مصوَّر" : imgs[i].src, forced); if (c) impDraft.push(c); else skipped++; });
    }
    out.innerHTML = impList() + (skipped ? `<p class="note warn">${skipped} سؤالًا لم يُستخرج (يعتمد على رسم أو لم يُقرأ كاملًا). أضيفيه بزر «تصوير سؤال» ليُحفظ بصورته.</p>` : "");
    applyLang(out);
  });
}
