const sentOf = (sid, tid) => (((S.acks[sid] || {}).sent) || {})[tid] || {};
const impFor = (sid, tid) => impsOf(tid).filter((m) => m.items[sid]).pop();
/** Improvement rounds already sent to this student: {impId: iso}. Reads the older single-round field too. */
const sentImps = (o) => Object.assign({}, o.imp && o.imp.id ? { [o.imp.id]: o.imp.at } : {}, o.imps || {});
/** A question as the student sees it: no model answer. */
