    S.acks[sid] = S.acks[sid] || { id: sid, seen: {}, notes: [] }; const o = ((S.acks[sid].sent = S.acks[sid].sent || {})[t.id] = S.acks[sid].sent[t.id] || {}); o.task = Object.assign({}, o.task, { sub, ev, tg: null });
