/* ---------- performance gap: each student against a target (a set criterion, her class mean, or the mean of all classes) ---------- */
const GAPM = { crit: "محكّ محدَّد", cls: "متوسط فصل الطالبة", all: "متوسط جميع الفصول" };
const gapCfg = () => Object.assign({ mode: "crit", crit: 80 }, S.settings.gap || {});
let _gapMemo = null;
function gapTarget(t, cls, mode) { // target % for the whole mark and for each cognitive level
  const c = gapCfg(); mode = mode || c.mode;
  if (mode === "crit") return { all: c.crit, K: c.crit, A: c.crit, R: c.crit };
  if (S.role === "student" && S.gapPre && S.gapPre[t.id]) return S.gapPre[t.id][mode === "cls" ? "cls" : "all"];
  if (!_gapMemo) { _gapMemo = {}; queueMicrotask(() => (_gapMemo = null)); }
  const key = t.id + "|" + (mode === "cls" ? cls : "");
  if (!_gapMemo[key]) { const g = groupStats(t, mode === "cls" ? cls : ""), o = { all: pct(g.mean, testMax(t)) }; ["K", "A", "R"].forEach((L) => (o[L] = g.levels[L].t ? pct(g.levels[L].c, g.levels[L].t) : null)); _gapMemo[key] = o; }
  return _gapMemo[key];
}
